// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2013, "2-3", [{"author":"К. Гилярова","question":"«Послезавтра у меня день рождения», — сказала Лиза в воскресенье. В какой день недели у Лизы день рождения?","choices":["в понедельник","во вторник","в среду","в пятницу","в субботу."],"key":"Б","review":["День рождения Лизы","Лиза говорит «послезавтра» в воскресенье. От воскресенья отсчитай «завтра» — это понедельник.","«Послезавтра» наступит сразу после «завтра». Следующий за понедельником день — вторник."]},{"author":"И. Рубанов","question":"― <em>Куда пошла мама?</em> ― спросила Маша у младшего брата.\n― <em>В магазин, купить кочан этой... как её...</em> ― ответил брат и запнулся. Но Маша всё равно сразу поняла, что мама пошла за ...","choices":["капустой","картошкой","морковкой","редиской","колбасой."],"key":"А","review":["Мама в магазине","Брат забыл название покупки, но успел сказать «кочан». Вспомни, что может расти кочаном.","Капустные листья образуют плотный круглый кочан. Картошку, морковь, редис и колбасу кочанами не называют."]},{"author":"И. Леенсон","question":"К какому слову <strong>нельзя</strong> добавить слово <em>слишком</em>?","choices":["<em>горячая</em>","<em>жидкая</em>","<em>солёная</em>","<em>манная</em>","<em>кислая</em>."],"key":"Г","review":["Как добавить «слишком»","«Слишком» значит, что какого-то свойства больше, чем нужно. Каша бывает слишком горячей, жидкой, солёной или кислой.","«Манная» сообщает, из какой крупы каша. В обычной речи у такого признака нет степени, поэтому «слишком манная» не подходит."]},{"author":"Б. Иомдин","question":"В рассказе Л. Пантелеева четырёхлетнюю девочку учат буквам:\n<em>— А это вот, Иринушка, буква «…».</em> Иринушка с удивлением на меня посмотрела и говорит:\n<em>— Ты?</em>\nКакую букву назвали Иринушке?","choices":["<em>А</em>","<em>И</em>","<em>Т</em>","<em>Ы</em>","<em>Я</em>."],"key":"Д","review":["Урок с Иринушкой","Иринушка ответила «Ты?», будто взрослый сказал что-то о себе. Какое из названий букв может означать «тот, кто говорит»?","Буква «Я» называется так же, как слово «я». Услышав это слово, девочка переспросила «Ты?»"]},{"author":"А. Сомин","question":"В одном из стихотворений С. Я. Маршака рассказывается, что Влас ― водопроводчик, Дима ― доктор, Толя ― тракторист, а Игорь ― …","choices":["шофёр","учитель","художник","инженер","электрик."],"key":"Г","review":["Герои Маршака","Сравни начало имени и профессии у каждого героя. У Власа и водопроводчика это В, у Димы и доктора Д, у Толи и тракториста Т.","Имя Игорь начинается с И. Из перечисленных профессий с И начинается «инженер»."]},{"author":"К. Гилярова","question":"Из какого слова <strong>нельзя</strong> получить другое слово, добавив букву <strong><em>у</em></strong> в начале?","choices":["<em>гол</em>","<em>дар</em>","<em>дочка</em>","<em>дача</em>","<em>из всех этих слов можно получить другое слово.</em>"],"key":"Д","review":["Буква у в начале","Поставь «у» перед «гол» и «дар». Получатся самостоятельные слова «угол» и «удар».","То же работает для «дочка» и «дача»: получаются «удочка» и «удача». Все четыре исходных слова подходят."]},{"author":"Е. Муравенко","question":"В каком слове на месте прочерков нужно вставить не такие гласные, как в остальных словах?","choices":["<em>г_л_дать</em>","<em>г_в_рить</em>","<em>г_л_ва</em>","<em>с_п_ги</em>","<em>х_р_шо</em>."],"key":"Г","review":["Пропущенные гласные","Восстанови «голодать», «говорить», «голова» и «хорошо». В обоих пропусках у каждого из этих слов пишется о.","«Сапоги» пишутся с а в первом слоге и о во втором. Здесь гласные в пропусках разные."]},{"author":"И. Иткин","question":"Газета «Гудок» была основана в 1917 году как газета...","choices":["железнодорожников","врачей","пекарей","плотников","театральных актёров."],"key":"А","review":["Название газеты","«Гудок» — это громкий сигнал. Вспомни, какой транспорт подавал такой сигнал на железной дороге.","Гудок подавал паровоз. Название «Гудок» связано с работой железнодорожников."]},{"author":"И. Рубанов","question":"<em>Дождь льёт как из</em> ...","choices":["<em>чашки</em>","<em>ложки</em>","<em>пушки</em>","<em>тучи</em>","<em>ведра</em>."],"key":"Д","review":["Сильный дождь","Представь, откуда может сразу вылиться много воды. Из чашки или ложки столько воды не польётся.","Сильный дождь сравнивают с водой, которую вылили из полного ведра. Поэтому говорят «льёт как из ведра»."]},{"author":"А. Сомин","question":"Болгарский язык родствен русскому. Какие профессии по-болгарски называются <em>разузнава́ч</em>, <em>кова́ч</em> и <em>чиста́ч</em>?","choices":["уборщик, разведчик, кузнец","разведчик, кузнец, уборщик","уборщик, кузнец, разведчик","разведчик, уборщик, кузнец","кузнец, разведчик, уборщик."],"key":"Б","review":["Профессии по-болгарски","В словах «разузнавач», «ковач» и «чистач» найди знакомые действия. Они похожи на «разузнавать», «ковать» и «чистить».","Разведчик разузнаёт, кузнец куёт металл, уборщик наводит чистоту. Эти профессии идут именно в таком порядке."]},{"author":"С. Бурлак","question":"Писатель дал своим героям необычные имена. Какое из них он не сможет перенести со строчки на строчку?","choices":["<em>Фаэт</em>","<em>Кария</em>","<em>Аталь</em>","<em>Эолинь</em>","<em>Астрель</em>."],"key":"В","review":["Перенос имён","При переносе обе части должны содержать гласную, и нельзя оставлять на строке одну букву. Например, возможны «Фа-эт», «Ка-рия», «Эо-линь» и «Ас-трель».","В «Аталь» согласная т перед гласной относится к следующему слогу. Деление «А-таль» оставляет одну букву в первой строке, поэтому переноса нет."]},{"author":"Е.Бикмаев","question":"Какое отчество у дочери Якова?","choices":["<em>Якововна</em>","<em>Яковична</em>","<em>Яковлична</em>","<em>Яковевна</em>","<em>Яковлевна</em>."],"key":"Д","review":["Дочь Якова","К именам часто добавляют «-овна» или «-евна», чтобы получить отчество дочери. У имени «Яков» при этом меняется основа.","Мужское отчество звучит «Яковлевич», а женское — «Яковлевна». В обоих перед суффиксом есть л."]},{"author":"Н. Валеева","question":"Бабушка связала Васе тёплый свитер и сказала: «<em>Вот наступит зима,</em> <em>и пригодится тебе эта…</em>».","choices":["<em>поделка</em>","<em>покупка</em>","<em>находка</em>","<em>новинка</em>","<em>обновка</em>."],"key":"Д","review":["Бабушкин подарок","Свитер бабушка сама связала. Подбери слово для новой вещи, которую Вася сможет надеть.","Новую одежду называют обновкой. «Покупка» подразумевает, что вещь купили, а «новинка» — что недавно появилось что-то новое."]},{"author":"Л. Фёдорова","question":"Повторять <em>Ой!</em> — это <em>ойкать</em>. А от какого слова обычно <strong>не</strong> образуется название действия?","choices":["<em>мяу</em>","<em>ква</em>","<em>ау</em>","<em>хи-хи</em>","<em>ха-ха</em>."],"key":"Д","review":["Возгласы и действия","Из «мяу» получается «мяукать», из «ква» — «квакать», из «ау» — «аукать», из «хи-хи» — «хихикать».","При громком «ха-ха» обычно говорят «хохотать». От самого «ха-ха» привычного глагола, такого как «ойкать», нет."]},{"author":"Л. Фёдорова","question":"На лужайке телёнок, ягнёнок, жеребёнок, овечка, овчарка. Кто из них родня барана?","choices":["овечка и овчарка","телёнок и ягнёнок","ягнёнок и овечка","жеребёнок и овчарка","овечка, ягнёнок и овчарка."],"key":"В","review":["Родня на лужайке","Найди взрослую самку и детёныша того же вида, что и баран. Самка — овечка, детёныш — ягнёнок.","Овчарка — собака, которая может пасти овец. Телёнок относится к коровам, жеребёнок — к лошадям. Родня барана — ягнёнок и овечка."]},{"author":"Б. Иомдин","question":"Будем составлять предложение из слов: <em>задачу</em>, <em>я</em>, <em>а</em>, <em>эту</em>, <em>решил</em> (не забыв в конце поставить точку). Какое слово надо поставить первым?","choices":["<em>задачу</em>","<em>я</em>","<em>а</em>","<em>эту</em>","<em>решил</em>."],"key":"В","review":["Слова в предложении","Соедини подлежащее «я» и сказуемое «решил», затем добавь «эту задачу». Осталось найти место для «а».","«А» связывает всё предложение с предыдущей мыслью. Его ставят в начало: «А я решил эту задачу»."]},{"author":"К. Гилярова","question":"Учитель музыки попросил закончить ряд: <em>гнездо</em>, <em>пюре</em>, <em>цунами</em>, <em>арфа</em>, <em>фасоль</em>, <em>кастрюля</em>, …","choices":["<em>сила</em>","<em>лягушка</em>","<em>такси</em>","<em>пианино</em>","<em>желе</em>."],"key":"В","review":["Ряд учителя музыки","Посмотри на концы слов. Гнез-до, пю-ре, цуна-ми, ар-фа дают первые четыре ноты.","Фасоль заканчивается на «соль», кастрюля на «ля». Следующая нота — «си», и на неё оканчивается «такси»."]},{"author":"Е. Муравенко","question":"В каком словосочетании слово <em>листок</em> можно понять по-разному?","choices":["<em>жёлтый листок</em>","<em>дубовый листок</em>","<em>берёзовый листок</em>","<em>опавший листок</em>","<em>тетрадный листок</em>."],"key":"А","review":["Два смысла листка","«Листок» может быть частью растения или маленьким листом бумаги. Сравни, какие прилагательные подходят к обоим значениям.","Дубовый, берёзовый и опавший листки обычно с дерева, тетрадный — бумажный. Жёлтым бывает и лист дерева, и лист бумаги."]},{"author":"Л. Фёдорова","question":"Миша писал сочинение об осени и вспоминал подходящие слова.\n<em>Тёмный</em> и <em>светлый</em> — пара слов с противоположным значением. Если слова <em>холодный</em>, <em>ясный</em>, <em>хмурый</em>, <em>тёплый</em>, <em>яркий</em> разбить на такие пары, одно останется лишним. Какое?","choices":["<em>холодный</em>","<em>ясный</em>","<em>хмурый</em>","<em>тёплый</em>","<em>яркий</em>."],"key":"Д","review":["Осенние слова","Собери пары противоположных по смыслу слов. К холоду подходит тепло, а ясная погода противоположна хмурой.","Получаются «холодный — тёплый» и «ясный — хмурый». Для «яркий» подошло бы «тусклый», но его в списке нет."]},{"author":"О. Подлесская","question":"Как заканчивается стихотворение Г. Ляховицкой «Забота»?\n<em>стать!</em>\n<em>настоящим</em>\n<em>джинном</em>\n<em>вырастать ―</em>\n<em>над кувшином</em>\n<em>вдруг огнём</em>\n<em>научиться</em>\n<em>ловко в нём,</em>\n<em>уместиться</em>\n<em>чтобы мог малютка-джиннчик</em>\n<em>нужен маленький кувшинчик,</em>\n<em>беспокоится о сыне:</em>\n<em>Взрослый джинн в большом кувшине</em>\n<em>Чтобы что-нибудь понять,</em>\n<em>надо ...</em>","choices":["<em>снова прочитать</em>","<em>громко прочитать</em>","<em>строчки сосчитать</em>","<em>снизу вверх читать</em>","<em>поперёк читать</em>."],"key":"Г","review":["Стихотворение о джинне","Найди строку с началом рассказа. «Взрослый джинн в большом кувшине» стоит почти в самом низу, а строкой выше он «беспокоится о сыне».","Если двигаться к верхней строке, складывается рассказ о маленьком джинне, которому надо вырасти. Поэтому стихи надо «снизу вверх читать»."]},{"author":"А. Пиперски","question":"Сколько в современном русском алфавите букв, названия которых не включают в себя сами эти буквы?","choices":["одна","две","три","четыре","пять."],"key":"В","review":["Названия букв","Читай названия букв и ищи в каждом саму букву. Например, в «бэ» есть б, в «эм» есть м, в «ща» есть щ.","В «и краткое» нет й, в «твёрдый знак» нет ъ, в «мягкий знак» нет ь. Таких букв три."]},{"author":"И. Рубанов","question":"В семье Ивановых Вася — средний из сыновей, а Таня — младшая из дочерей. Что можно точно сказать про эту семью?","choices":["в ней не больше четырёх детей","в ней не больше пяти детей","в ней не больше шести детей","в ней не меньше пяти детей","в ней не меньше шести детей."],"key":"Г","review":["Дети Ивановых","У среднего сына есть хотя бы один старший и один младший брат. Значит, сыновей трое или больше.","У младшей дочери хотя бы одна старшая сестра. Всего детей как минимум три плюс два — пять. Верхнюю границу узнать нельзя."]},{"author":"А. Иткин и И. Иткин","question":"Сколько в русском языке названий месяцев, состоящих ровно из пяти звуков?","choices":["ни одного","одно","два","три","четыре."],"key":"Б","review":["Звуки в названиях месяцев","В названиях «май» три звука, а «март», «июнь» и «июль» дают по четыре. В июне и июле «ю» после «и» даёт [й’] и [у], а ь отдельного звука не даёт.","Произнеси «апрель»: слышны [а], [п], [р’], [э], [л’]. У остальных месяцев шесть звуков или больше, поэтому подходит один месяц."]},{"author":"Е. Муравенко","question":"В какой паре слова связаны по смыслу не так, как в остальных?","choices":["<em>солить ― соль</em>","<em>красить ― краска</em>","<em>клеить ― клей</em>","<em>пудрить ― пудра</em>","<em>рисовать ― рисунок</em>."],"key":"Д","review":["Действие и предмет","Солят солью, красят краской, клеят клеем, пудрят пудрой. В каждой из этих пар названо то, чем выполняют действие.","Рисунок — то, что получается после рисования. Рисуют, например, карандашом или красками."]},{"author":"Н. Валеева","question":"Даны слова: <em>выпучить</em>, <em>выпятить</em>, <em>надуть</em>, <em>оскалить</em>. Что лишнее?","choices":["<em>щёки</em>","<em>нос</em>","<em>зубы</em>","<em>грудь</em>","<em>глаза</em>."],"key":"Б","review":["Что с чем делают","Вспомни привычные выражения: выпучить глаза, выпятить грудь, надуть щёки, оскалить зубы.","Каждому глаголу нашлась своя часть тела. Нос остался без пары: про него обычно говорят, например, «задрать нос»."]},{"author":"М. Тюренкова","question":"К 1878 году в семье известного русского купца и покровителя искусств Саввы Ивановича Мамонтова было четверо детей: <em>Сергей</em>, <em>Андрей</em>, <em>Всеволод</em>, <em>Вера</em>. В 1878 году родилась дочь, которую назвали ...","choices":["<em>Вероника</em>","<em>Александра</em>","<em>Ольга</em>","<em>Елизавета</em>","<em>Катерина</em>."],"key":"Б","review":["Дети Саввы Мамонтова","Возьми первые буквы имён детей по порядку. Сергей, Андрей, Всеволод, Вера дают «САВВ».","Для имени отца «САВВА» нужна ещё одна А. Из вариантов на А начинается только Александра."]},{"author":"Е. Муравенко","question":"Родители назвали дочь и сына именами, начинающимися с одного и того же звука. Детей зовут ...","choices":["<em>Юля</em> и <em>Ян</em>","<em>Оля</em> и <em>Олег</em>","<em>Маша</em> и <em>Миша</em>","<em>Соня</em> и <em>Сеня</em>","<em>Надя</em> и <em>Даня</em>."],"key":"А","review":["Первые звуки имён","В начале «Юля» буква ю даёт [й’] и [у], а в начале «Ян» буква я даёт [й’] и [а]. Первым в обоих случаях слышится [й’].","В «Оля» и «Олег» начальная о звучит по-разному из-за ударения. В «Маша — Миша» и «Соня — Сеня» различается мягкость первых согласных, в «Надя — Даня» различаются сами согласные."]},{"author":"Н. Валеева","question":"Педро Санчес Гарсиа — испанец. Его папу зовут Антонио Санчес\nРодригес, а маму — Мария Гарсиа Веласкес. Хуан Фернандес Гомес тоже испанец. Как могут звать его родителей?","choices":["Федерико Гомес Лопес и Тереса Санчес Фернандес","Диего Фернандес Гарсиа и Лусия Санчес Родригес","Хосе Гомес Фернандес и Хуана Гарсиа Лопес","Алехандро Фернандес Лопес и Луиса Гомес Гарсиа","Мигель Гарсиа Фернандес и Рамона Фернандес Санчес."],"key":"Г","review":["Испанские фамилии","Сравни полные имена Педро и его родителей. От отца он получил его первую фамилию Санчес, от матери — её первую фамилию Гарсиа.","У папы Хуана первой должна быть Фернандес, у мамы — Гомес. Это Алехандро Фернандес Лопес и Луиса Гомес Гарсиа."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
